<?php partial('account_nav',['route'=>$route]);$uid=(int)$me['id'];$page=max(1,min(100000,(int)($_GET['page']??1)));$total=(int)$a->db->value('SELECT COUNT(*) FROM cy_messages WHERE sender_id=? OR recipient_id=?',[$uid,$uid]);$messages=$a->db->all('SELECT m.*,s.display_name AS sender_name,s.username AS sender_user,r.display_name AS recipient_name,r.username AS recipient_user FROM cy_messages m JOIN cy_users s ON s.id=m.sender_id JOIN cy_users r ON r.id=m.recipient_id WHERE m.sender_id=? OR m.recipient_id=? ORDER BY m.id DESC LIMIT 30 OFFSET ?',[$uid,$uid,($page-1)*30]); ?><section class="page-hero"><div><span class="eyebrow">A MORE PERSONAL CONVERSATION</span><h1><?= e($title) ?></h1></div><?= form_start('read_messages') ?><?php button('Mark all as read','secondary small','check'); ?></form></section><div class="two-column"><section class="panel glass"><h2><?= t('Send a little hello') ?></h2><?= form_start('message') ?><?php field('recipient','Recipient username',\Chengyu\Core\Input::text($_GET['to']??'',32),'text',['required'=>'required']);field('body','Your message','','textarea',['required'=>'required','maxlength'=>'4000']);button('Send message','full','message'); ?><p class="hint"><?= t('Messages are stored on this site and are not end-to-end encrypted. Do not send secrets or payment credentials.') ?></p></form></section><section class="panel glass"><h2><?= t('Recent conversations') ?></h2><?php foreach ($messages as $message): $sent=(int)$message['sender_id']===$uid; ?><article class="message-item <?= $sent?'sent':'' ?>"><span class="message-symbol"><?= icon($sent?'arrow':'message') ?></span><div class="grow"><div class="message-head"><strong><?= e($sent?$message['recipient_name']:$message['sender_name']) ?></strong><span class="pill"><?= t($sent?'Sent':'Received') ?></span></div><p class="message-bubble"><?= nl2br(e($message['body'])) ?></p><small><?= dt((int)$message['created_at'],'m.d H:i') ?> &middot; <a href="<?= e(url('messages',['to'=>$sent?$message['recipient_user']:$message['sender_user']])) ?>"><?= t('Reply') ?></a></small></div></article><?php endforeach ?><?php if (!$messages) {empty_state('Your next conversation starts here.','message');} partial('pagination',['route'=>$route,'pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section></div>
